function planDst({zones,instant}){
 if(!Array.isArray(zones)||zones.some(z=>typeof z!=='string'||!z.trim())||new Set(zones).size!==zones.length)throw Error('Configure distinct IANA time zones');
 const now=instant===null||instant===undefined?Date.now():Date.parse(instant);if(!Number.isFinite(now))throw Error('Invalid time');
 const alerts=[];
 for(const zone of zones){
  let fmt,off;try{fmt=new Intl.DateTimeFormat('en-CA-u-ca-iso8601',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'});off=new Intl.DateTimeFormat('en-US',{timeZone:zone,timeZoneName:'shortOffset'});}catch{throw Error('Invalid time zone: '+zone)}
  const dateKey=t=>{let p=Object.fromEntries(fmt.formatToParts(new Date(t)).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day};
  const keyAt=d=>new Date(d).toISOString().slice(0,10), today=dateKey(now),base=Date.parse(today+'T00:00:00Z'),tomorrow=keyAt(base+86400000),after=keyAt(base+172800000);
  function boundary(key,center){let lo=center-36*3600000,hi=center+36*3600000;while(lo<hi){let mid=Math.floor((lo+hi)/2);if(dateKey(mid)<key)lo=mid+1;else hi=mid;}return lo;}
  const offset=t=>{let v=off.formatToParts(new Date(t)).find(x=>x.type==='timeZoneName')?.value;if(v==='GMT')return 0;let m=/^GMT([+-])(\d{1,2})(?::(\d{2}))?$/.exec(v);if(!m)throw Error('Unsupported time zone offset');return (m[1]==='-'?-1:1)*(Number(m[2])*60+Number(m[3]||0));};
  function isDst(t){const d=dateKey(t),[y,m,day]=d.split('-').map(Number),jan=Date.UTC(y,0,2),may=Date.UTC(y,4,day+1);return offset(t)>offset(boundary(keyAt(jan),jan)-1000)||offset(t)>offset(boundary(keyAt(may),may)-1000);}
  const start=boundary(tomorrow,base+86400000),end=boundary(after,base+172800000);if(dateKey(start)!==tomorrow||dateKey(end-1)!==tomorrow)throw Error('Cannot identify tomorrow in '+zone);
  if(isDst(start-1000)!==isDst(end-1000)){const message='Tomorrow is Daylight Saving Time change in zone '+zone+' - remember to adjust meeting times!';alerts.push({zone,message,subject:'DST change tomorrow in '+zone});}
 }
 return {alerts};
}

const zones = ['America/New_York','Europe/Warsaw'];
return planDst({zones,instant:null}).alerts.map((alert,index)=>({json:alert,pairedItem:{item:0}}));
